insert into public.demo_plant_care values ('Monstera deliciosa',array[]::text[],'{"commonName":"มอนสเตอร่า","description":"ข้อมูลดูแลจาก dataset Supabase: ตรวจดินชั้นบนให้แห้งก่อนรดน้ำ ใช้ดินระบายน้ำดีและแสงสว่างที่กรองแล้ว","wateringIntervalDays":null,"sunlightRequirement":"medium","temperatureMinC":null,"temperatureMaxC":null,"careDifficulty":"unknown","warnings":["ตรวจสภาพแวดล้อมและความชื้นดินจริงก่อนดูแล","ข้อมูลความเป็นพิษ: ยังไม่มีข้อมูลเพียงพอ"]}'::jsonb,'https://www.rhs.org.uk/plants/swiss-cheese-plants/how-to-grow-swiss-cheese-plants');
insert into public.demo_plant_care values ('Epipremnum aureum',array[]::text[],'{"commonName":"พลูด่าง","description":"ข้อมูลดูแลจาก dataset Supabase: ใช้แสงสว่างกรองแล้วและดินระบายน้ำดี ตรวจความชื้นก่อนให้น้ำ ไม่ปล่อยน้ำขัง","wateringIntervalDays":null,"sunlightRequirement":"medium","temperatureMinC":null,"temperatureMaxC":null,"careDifficulty":"unknown","warnings":["ตรวจสภาพแวดล้อมและความชื้นดินจริงก่อนดูแล","ข้อมูลความเป็นพิษ: ยังไม่มีข้อมูลเพียงพอ"]}'::jsonb,'https://www.rhs.org.uk/plants/91403/epipremnum-aureum/details');
insert into public.demo_plant_care values ('Dracaena trifasciata',array['Sansevieria trifasciata']::text[],'{"commonName":"ลิ้นมังกร","description":"ข้อมูลดูแลจาก dataset Supabase: วางในบริเวณสว่าง รอวัสดุปลูกแห้งก่อนรดน้ำ ใช้กระถางระบายน้ำดี","wateringIntervalDays":null,"sunlightRequirement":"medium","temperatureMinC":null,"temperatureMaxC":null,"careDifficulty":"unknown","warnings":["ตรวจสภาพแวดล้อมและความชื้นดินจริงก่อนดูแล","ข้อมูลความเป็นพิษ: ยังไม่มีข้อมูลเพียงพอ"]}'::jsonb,'https://www.kew.org/plants/snake-plant');
insert into public.demo_plant_care values ('Ocimum basilicum',array[]::text[],'{"commonName":"โหระพา","description":"ข้อมูลดูแลจาก dataset Supabase: ให้แสงเพียงพอและอากาศอบอุ่น ตรวจดินไม่ให้แห้งจัดหรือแฉะ ปรับน้ำตามสภาพจริง","wateringIntervalDays":null,"sunlightRequirement":"high","temperatureMinC":null,"temperatureMaxC":null,"careDifficulty":"unknown","warnings":["ตรวจสภาพแวดล้อมและความชื้นดินจริงก่อนดูแล","ข้อมูลความเป็นพิษ: ยังไม่มีข้อมูลเพียงพอ"]}'::jsonb,'https://www.rhs.org.uk/herbs/basil/grow-your-own');
insert into public.demo_plant_care values ('Echinocactus grusonii',array['Kroenleinia grusonii']::text[],'{"commonName":"กระบองเพชรถังทอง","description":"ข้อมูลดูแลจาก dataset Supabase: ให้แสงสว่างมากและวัสดุปลูกโปร่ง รอวัสดุปลูกแห้งก่อนรดน้ำ ระวังหนาม","wateringIntervalDays":null,"sunlightRequirement":"high","temperatureMinC":null,"temperatureMaxC":null,"careDifficulty":"unknown","warnings":["ตรวจสภาพแวดล้อมและความชื้นดินจริงก่อนดูแล","ข้อมูลความเป็นพิษ: ยังไม่มีข้อมูลเพียงพอ"]}'::jsonb,'https://herbaria.plants.ox.ac.uk/bol/plants400/Profiles/EF/Echinocactus');
