create table public.demo_plant_care (scientific_name text primary key, aliases text[] not null default '{}', care jsonb not null check(jsonb_typeof(care)='object'), source_url text not null);
alter table public.demo_plant_care enable row level security;
revoke all on public.demo_plant_care from public, anon, authenticated;
grant select on public.demo_plant_care to service_role;
